  lateFee(issued, '2026-10-31');
  const after = JSON.stringify(issued);

  assert.equal(before, after);
});

test('lateFee with large overdue amount', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'LOGO-PACK', qty: 5, discountPercent: 0 }],
    terms: 'NET14',
  });
  assert.equal(r.ok, true);
  const draft = r.value;

  const r2 = issueInvoice(draft, []);
  assert.equal(r2.ok, true);
  const issued = r2.value; // Due 2026-10-15

  // 10 days after due date
  const fee = lateFee(issued, '2026-10-25');
  // Amount due: 5 * 120000 * (1 + 0.21) = 726000 cents (includes VAT)
  // Fee: 726000 * 0.0004 * 10 = 2904 cents
  assert.equal(fee, 2904);
});
